<script setup lang="ts">
import { Head, router, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import AppLayout from '../../../layouts/AppLayout.vue';

interface Term { id:number; name:string; semester_type:'odd'|'even'; start_date:string; end_date:string; is_active:boolean }
interface Year { id:number; name:string; start_date:string; end_date:string; is_active:boolean; terms:Term[] }
interface Subject { id:number; code:string; name:string; category?:string|null; order:number; is_active:boolean }
defineProps<{ academic_years:Year[]; subjects:Subject[] }>();

const showYear=ref(false), showTerm=ref(false), showSubject=ref(false);
const selectedYear=ref<Year|null>(null), selectedSubject=ref<Subject|null>(null);
const yearForm=useForm({name:'',start_date:'',end_date:''});
const termForm=useForm({name:'Semester Ganjil',semester_type:'odd',start_date:'',end_date:''});
const subjectForm=useForm({code:'',name:'',category:'Wajib',order:0,is_active:true});

const editYear=(item:Year)=>{selectedYear.value=item;yearForm.name=item.name;yearForm.start_date=item.start_date.slice(0,10);yearForm.end_date=item.end_date.slice(0,10);showYear.value=true};
const openTerm=(item:Year)=>{selectedYear.value=item;termForm.reset();showTerm.value=true};
const editSubject=(item?:Subject)=>{selectedSubject.value=item??null;subjectForm.code=item?.code??'';subjectForm.name=item?.name??'';subjectForm.category=item?.category??'Wajib';subjectForm.order=item?.order??0;subjectForm.is_active=item?.is_active??true;showSubject.value=true};
const saveYear=()=>{const method=selectedYear.value?'put':'post';const url=selectedYear.value?`/akademik/pengaturan/tahun-ajaran/${selectedYear.value.id}`:'/akademik/pengaturan/tahun-ajaran';yearForm[method](url,{onSuccess:()=>{showYear.value=false;selectedYear.value=null;yearForm.reset()}})};
const saveTerm=()=>{if(!selectedYear.value)return;termForm.post(`/akademik/pengaturan/tahun-ajaran/${selectedYear.value.id}/semester`,{onSuccess:()=>{showTerm.value=false;termForm.reset()}})};
const saveSubject=()=>{const method=selectedSubject.value?'put':'post';const url=selectedSubject.value?`/akademik/pengaturan/mata-pelajaran/${selectedSubject.value.id}`:'/akademik/pengaturan/mata-pelajaran';subjectForm[method](url,{onSuccess:()=>{showSubject.value=false;selectedSubject.value=null;subjectForm.reset()}})};
</script>

<template><AppLayout title="Pengaturan Akademik"><Head title="Pengaturan Akademik"/><main class="view space-y-6">
<section class="hero-card settings-hero"><div><p class="eyebrow">Konfigurasi akademik</p><h1>Periode & mata pelajaran</h1><p>Kelola tahun ajaran, semester aktif, dan katalog mata pelajaran sekolah.</p></div><div class="hero-actions"><button class="secondary-button" @click="selectedYear=null;yearForm.reset();showYear=true">Tambah tahun ajaran</button><button class="primary-button" @click="editSubject()">Tambah mata pelajaran</button></div></section>
<section class="settings-grid"><div class="panel settings-panel"><div class="panel-heading"><div><p class="eyebrow">Kalender akademik</p><h2>Tahun ajaran & semester</h2></div></div><div class="record-list"><article v-for="year in academic_years" :key="year.id" class="record-card"><div class="record-main"><div><span v-if="year.is_active" class="status-pill">Aktif</span><h3>{{year.name}}</h3><small>{{year.start_date.slice(0,10)}} — {{year.end_date.slice(0,10)}}</small></div><div class="actions"><button class="text-button" @click="editYear(year)">Ubah</button><button class="text-button" @click="openTerm(year)">Tambah semester</button><button v-if="!year.is_active" class="text-button" @click="router.post(`/akademik/pengaturan/tahun-ajaran/${year.id}/aktifkan`)">Aktifkan</button></div></div><div class="term-list"><div v-for="term in year.terms" :key="term.id"><span>{{term.name}}</span><small>{{term.semester_type==='odd'?'Ganjil':'Genap'}} · {{term.start_date.slice(0,10)}}—{{term.end_date.slice(0,10)}}</small><button v-if="!term.is_active" @click="router.post(`/akademik/pengaturan/semester/${term.id}/aktifkan`)">Jadikan aktif</button><strong v-else>Semester aktif</strong></div></div></article><div v-if="!academic_years.length" class="empty-state">Belum ada tahun ajaran.</div></div></div>
<div class="panel settings-panel"><div class="panel-heading"><div><p class="eyebrow">Katalog</p><h2>Mata pelajaran</h2></div></div><div class="subject-list"><article v-for="item in subjects" :key="item.id"><span class="subject-code">{{item.code}}</span><div><h3>{{item.name}}</h3><small>{{item.category||'Tanpa kategori'}} · urutan {{item.order}} · {{item.is_active?'aktif':'nonaktif'}}</small></div><div class="actions"><button class="text-button" @click="editSubject(item)">Ubah</button><button class="danger-link" @click="router.delete(`/akademik/pengaturan/mata-pelajaran/${item.id}`)">Hapus</button></div></article></div></div></section>
</main>
<div v-if="showYear" class="modal-backdrop" @click.self="showYear=false"><form class="modal-card" @submit.prevent="saveYear"><h2>{{selectedYear?'Ubah':'Tambah'}} tahun ajaran</h2><label>Nama<input v-model="yearForm.name" required placeholder="2027/2028"/></label><div class="form-grid"><label>Mulai<input v-model="yearForm.start_date" type="date" required/></label><label>Selesai<input v-model="yearForm.end_date" type="date" required/></label></div><div class="modal-actions"><button type="button" class="secondary-button" @click="showYear=false">Batal</button><button class="primary-button">Simpan</button></div></form></div>
<div v-if="showTerm" class="modal-backdrop" @click.self="showTerm=false"><form class="modal-card" @submit.prevent="saveTerm"><h2>Tambah semester · {{selectedYear?.name}}</h2><label>Nama<input v-model="termForm.name" required/></label><label>Jenis<select v-model="termForm.semester_type"><option value="odd">Ganjil</option><option value="even">Genap</option></select></label><div class="form-grid"><label>Mulai<input v-model="termForm.start_date" type="date" required/></label><label>Selesai<input v-model="termForm.end_date" type="date" required/></label></div><div class="modal-actions"><button type="button" class="secondary-button" @click="showTerm=false">Batal</button><button class="primary-button">Simpan</button></div></form></div>
<div v-if="showSubject" class="modal-backdrop" @click.self="showSubject=false"><form class="modal-card" @submit.prevent="saveSubject"><h2>{{selectedSubject?'Ubah':'Tambah'}} mata pelajaran</h2><div class="form-grid"><label>Kode<input v-model="subjectForm.code" required/></label><label>Urutan<input v-model.number="subjectForm.order" type="number" min="0" required/></label></div><label>Nama<input v-model="subjectForm.name" required/></label><label>Kategori<input v-model="subjectForm.category"/></label><label class="check"><input v-model="subjectForm.is_active" type="checkbox"/> Mata pelajaran aktif</label><div class="modal-actions"><button type="button" class="secondary-button" @click="showSubject=false">Batal</button><button class="primary-button">Simpan</button></div></form></div>
</AppLayout></template>
<style scoped>.settings-hero,.hero-actions,.panel-heading,.record-main,.actions,.modal-actions{display:flex;align-items:center}.settings-hero,.panel-heading,.record-main{justify-content:space-between}.settings-hero{gap:1.5rem}.hero-actions,.actions,.modal-actions{gap:.7rem}.settings-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:1.25rem}.settings-panel{overflow:hidden}.panel-heading{padding:1.1rem 1.25rem;border-bottom:1px solid #e2e8f0}.panel-heading h2,.record-card h3,.subject-list h3,.modal-card h2{font-weight:800;color:#0f172a}.record-list,.subject-list{display:grid;gap:.75rem;padding:1rem}.record-card,.subject-list article{padding:1rem;border:1px solid #e2e8f0;border-radius:.85rem}.status-pill{display:inline-block;padding:.15rem .45rem;border-radius:999px;background:#dcfce7;color:#15803d;font-size:.65rem;font-weight:800}.record-main small,.subject-list small,.term-list small{display:block;color:#64748b}.term-list{display:grid;gap:.45rem;margin-top:.8rem;padding-top:.8rem;border-top:1px solid #e2e8f0}.term-list>div{display:grid;grid-template-columns:1fr 2fr auto;align-items:center;gap:.5rem;padding:.5rem;border-radius:.55rem;background:#f8fafc;font-size:.78rem}.term-list button,.term-list strong,.text-button{color:#4f46e5;font-size:.72rem;font-weight:800}.subject-list article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.75rem}.subject-code{padding:.4rem;border-radius:.5rem;background:#eef2ff;color:#4338ca;font-weight:800}.danger-link{color:#dc2626;font-size:.72rem;font-weight:800}.modal-backdrop{position:fixed;inset:0;z-index:80;display:grid;place-items:center;background:rgb(15 23 42/.56);padding:1rem}.modal-card{width:min(560px,100%);display:grid;gap:1rem;padding:1.3rem;border-radius:1rem;background:white}.modal-card label{display:grid;gap:.35rem;color:#334155;font-size:.8rem;font-weight:700}.modal-card input,.modal-card select{padding:.65rem;border:1px solid #cbd5e1;border-radius:.6rem}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.check{display:flex!important;align-items:center}.check input{width:auto}.modal-actions{justify-content:flex-end}@media(max-width:850px){.settings-grid{grid-template-columns:1fr}.settings-hero{align-items:flex-start;flex-direction:column}.term-list>div{grid-template-columns:1fr}}</style>
